-- Курсы скорочтения 96 (педагогам) и 97 (детям): программы и уроки.
INSERT INTO t_p78828167_tutor_platform_1.course_curricula (course_id,course_title,subject,grade_band,total_lessons,total_modules,estimated_hours,program_description,learning_outcomes,target_audience,prerequisites,methodology,final_project,certificate_available,generated_by,version,is_fallback,age_rating) VALUES (96,'Преподаватель скорочтения для детей','russian','adult',36,6,24,'Профессиональная программа для педагогов: как устроено чтение, диагностика скорости и понимания, упражнения на поле зрения, внимание, память и антиципацию, работа с особыми случаями, готовые планы 16 занятий и запуск частной практики.','["Проводите диагностику скорости и понимания чтения", "Подбираете упражнения под причину медленного чтения", "Ведёте занятия по готовым планам 16 встреч для детей 6–12 лет", "Работаете с регрессиями, проговариванием и низкой мотивацией", "Объясняете родителям результат и показываете прогресс", "Запускаете частную практику: формат, цена, первые ученики"]'::jsonb,'Учителя начальных классов, логопеды, дефектологи, репетиторы, воспитатели и все, кто хочет преподавать скорочтение детям.','["педагогический опыт не обязателен", "готовность заниматься с детьми 6–12 лет"]'::jsonb,'Короткие уроки с примерами и разборами занятий. В каждом модуле — практика: упражнения на себе, разработка занятия, диагностика ученика. ИИ-наставник 24/7 отвечает на вопросы и проверяет задания.','Итоговый проект: диагностика реального ребёнка, индивидуальный план из 16 занятий и отчёт для родителей.',true,'editorial_manual',1,false,'18+');
INSERT INTO t_p78828167_tutor_platform_1.course_lessons (course_id,module_index,module_title,module_description,lesson_index,lesson_title,lesson_summary,lesson_type,estimated_minutes,topics,skills_acquired,homework_description,is_preview,sort_order)
SELECT 96, m.mi::int, m.mod->>'t', m.mod->>'d', l.li::int, l.les->>0, l.les->>1, l.les->>2,
  CASE l.les->>2 WHEN 'theory' THEN 25 WHEN 'project' THEN 45 ELSE 35 END,
  l.les->3, '[]'::jsonb, 'Выполните задание урока «' || (l.les->>0) || '» и отметьте результат в дневнике.',
  (m.mi = 1 AND l.li = 1), ((m.mi - 1) * 6 + l.li)::int
FROM jsonb_array_elements('[{"t": "Модуль 1. Как устроено чтение", "d": "Навыки, из которых складывается быстрое чтение с пониманием.", "l": [["Пять опор быстрого чтения", "Техника, поле зрения, память, внимание, словарь.", "theory", ["Навыки чтения", "Поле зрения", "Память", "Внимание"]], ["Почему современные дети читают медленно", "Регрессии, проговаривание, узкое поле зрения, слабая мотивация.", "theory", ["Регрессии", "Проговаривание", "Мотивация", "Гаджеты"]], ["Возрастные особенности 6–12 лет", "Что можно требовать от ребёнка в каждом возрасте.", "theory", ["Возраст", "Нагрузка", "Утомляемость", "Нормы"]], ["Готовность к чтению у дошкольников", "Фонематический слух, звуко-буквенный анализ.", "theory", ["Фонематический слух", "Слоги", "Подготовка", "6–7 лет"]], ["Когда нужен логопед", "Признаки дислексии и других нарушений.", "theory", ["Дислексия", "Логопед", "Направление", "Границы"]], ["Практика: разбор трёх случаев", "Определяем причины медленного чтения по описанию.", "practice", ["Разбор", "Причины", "Кейсы", "Выводы"]]]}, {"t": "Модуль 2. Диагностика", "d": "Замер скорости, понимания и сопутствующих навыков.", "l": [["Как замерить скорость чтения", "Подбор текста, подсчёт слов, ориентиры по классам.", "practice", ["Скорость", "Слова в минуту", "Тексты", "Нормы"]], ["Как проверить понимание", "Вопросы, пересказ, работа с главной мыслью.", "practice", ["Понимание", "Вопросы", "Пересказ", "Главная мысль"]], ["Диагностика внимания и памяти", "Простые пробы на первом занятии.", "practice", ["Внимание", "Память", "Пробы", "Шульте"]], ["Карта ученика", "Фиксируем результаты и ставим цели.", "practice", ["Карта ученика", "Цели", "Документ", "Прогресс"]], ["Пробное занятие за 30 минут", "Сценарий диагностической встречи.", "practice", ["Пробное занятие", "Сценарий", "Родители", "Выводы"]], ["Практика: диагностика ученика", "Проводим полную диагностику и заполняем карту.", "practice", ["Диагностика", "Карта", "Отчёт", "Практика"]]]}, {"t": "Модуль 3. Тренажёры и упражнения", "d": "Инструменты педагога скорочтения.", "l": [["Таблицы Шульте", "Варианты, усложнения и нормы времени.", "practice", ["Шульте", "Внимание", "Периферия", "Усложнения"]], ["Поле зрения: клин и пирамиды", "Учим читать словами и фразами.", "practice", ["Клин", "Пирамиды", "Поле зрения", "Фразы"]], ["Антиципация", "Угадывание окончаний, пропущенные слова, закрытая строка.", "practice", ["Антиципация", "Окончания", "Пропуски", "Смысл"]], ["Борьба с регрессиями и проговариванием", "Указка, темп, ритмичное чтение.", "practice", ["Регрессии", "Проговаривание", "Указка", "Темп"]], ["Память и концентрация", "Игры на удержание и воспроизведение.", "practice", ["Память", "Концентрация", "Игры", "Пересказ"]], ["Практика: банк из 30 упражнений", "Собираем свой набор под возраст и цели.", "practice", ["Банк упражнений", "Подбор", "Возраст", "Цели"]]]}, {"t": "Модуль 4. Занятие и курс", "d": "Структура урока и программа на 2 месяца.", "l": [["Структура занятия на 45 минут", "Разминка, тренажёры, чтение, игра и итог.", "theory", ["Занятие", "Структура", "Тайминг", "Итог"]], ["Программа из 16 встреч", "Как растёт сложность от занятия к занятию.", "theory", ["Программа", "16 встреч", "Сложность", "Этапы"]], ["Домашние задания", "10–15 минут в день и контроль выполнения.", "practice", ["Домашка", "Регулярность", "Контроль", "Дневник"]], ["Групповые занятия", "Мини-группы 3–5 детей: как удержать внимание.", "practice", ["Группа", "Дисциплина", "Игры", "Темп"]], ["Онлайн-формат", "Инструменты и приёмы для занятий по видеосвязи.", "practice", ["Онлайн", "Видеосвязь", "Доска", "Вовлечение"]], ["Практика: план 16 занятий", "Составляем программу для конкретного ученика.", "practice", ["План", "Ученик", "Программа", "Цели"]]]}, {"t": "Модуль 5. Мотивация и родители", "d": "Как удержать ученика и показать результат.", "l": [["Мотивация ребёнка", "Игровые механики, рекорды, похвала за усилие.", "theory", ["Мотивация", "Игра", "Рекорды", "Похвала"]], ["Подбор книг", "Тексты по интересам и уровню.", "theory", ["Книги", "Интересы", "Уровень", "Чтение"]], ["Разговор с родителями", "Ожидания, честные обещания, обратная связь.", "theory", ["Родители", "Ожидания", "Обещания", "Обратная связь"]], ["Отчёт о прогрессе", "Замеры, график, рекомендации.", "practice", ["Отчёт", "График", "Замеры", "Рекомендации"]], ["Сложные ситуации", "Ребёнок не хочет заниматься, родители давят.", "practice", ["Конфликты", "Отказ", "Давление", "Решения"]], ["Практика: отчёт для родителей", "Готовим промежуточный отчёт по ученику.", "practice", ["Отчёт", "Родители", "Прогресс", "Документ"]]]}, {"t": "Модуль 6. Частная практика", "d": "Формат, цена, ученики и первый доход.", "l": [["Форматы работы", "Онлайн, мини-группы, кабинет: плюсы и минусы.", "theory", ["Форматы", "Онлайн", "Кабинет", "Группы"]], ["Как назначить цену", "Анализ рынка, пакеты занятий, предоплата.", "theory", ["Цена", "Пакеты", "Рынок", "Предоплата"]], ["Первые ученики", "Тёплый круг, родительские чаты, сарафан.", "practice", ["Ученики", "Чаты", "Сарафан", "Посты"]], ["Документы и налоги", "Самозанятость, договор с родителями, чеки.", "theory", ["Самозанятость", "Договор", "Чеки", "Налоги"]], ["Личный бренд педагога", "Соцсети, кейсы, отзывы.", "practice", ["Бренд", "Соцсети", "Кейсы", "Отзывы"]], ["Итоговый проект", "Диагностика ребёнка, план 16 занятий и отчёт — защита.", "project", ["Итоговый проект", "Диагностика", "План", "Защита"]]]}]'::jsonb) WITH ORDINALITY AS m(mod, mi)
CROSS JOIN LATERAL jsonb_array_elements(m.mod->'l') WITH ORDINALITY AS l(les, li);
INSERT INTO t_p78828167_tutor_platform_1.course_curricula (course_id,course_title,subject,grade_band,total_lessons,total_modules,estimated_hours,program_description,learning_outcomes,target_audience,prerequisites,methodology,final_project,certificate_available,generated_by,version,is_fallback,age_rating) VALUES (97,'Скорочтение для детей 6–11 лет','russian','1-4',24,4,8,'Короткие ежедневные занятия по 15 минут: замер скорости и понимания, игры на внимание, память и поле зрения, понимание текста и пересказ, подбор книг по интересам. Повторные замеры показывают прогресс.','["Ребёнок читает словами, а не по слогам", "Меньше возвращается к прочитанному", "Лучше понимает и пересказывает текст", "Дольше удерживает внимание", "Сам выбирает книги и читает с интересом"]'::jsonb,'Дети 6–11 лет и их родители: от подготовки к школе до 4–5 класса.','["ребёнок знает буквы и умеет читать хотя бы по слогам", "10–15 минут в день"]'::jsonb,'Игровые занятия по 15 минут каждый день. Тренажёры, короткие тексты и вопросы на понимание. Родитель получает подсказки, как помочь без давления. ИИ-наставник отвечает на вопросы ребёнка и родителя.','Финальный замер скорости и понимания и сравнение с первым занятием.',true,'editorial_manual',1,false,'6+');
INSERT INTO t_p78828167_tutor_platform_1.course_lessons (course_id,module_index,module_title,module_description,lesson_index,lesson_title,lesson_summary,lesson_type,estimated_minutes,topics,skills_acquired,homework_description,is_preview,sort_order)
SELECT 97, m.mi::int, m.mod->>'t', m.mod->>'d', l.li::int, l.les->>0, l.les->>1, l.les->>2,
  CASE l.les->>2 WHEN 'project' THEN 20 ELSE 15 END,
  l.les->3, '[]'::jsonb, 'Выполните задание урока «' || (l.les->>0) || '» и отметьте результат в дневнике.',
  (m.mi = 1 AND l.li = 1), ((m.mi - 1) * 6 + l.li)::int
FROM jsonb_array_elements('[{"t": "Модуль 1. Старт и замер", "d": "Узнаём скорость чтения и разогреваем внимание.", "l": [["Знакомство и первый замер", "Читаем текст и отвечаем на вопросы.", "practice", ["Замер", "Скорость", "Понимание", "Старт"]], ["Таблица Шульте: первые рекорды", "Учимся искать числа по порядку.", "practice", ["Шульте", "Внимание", "Рекорд", "Игра"]], ["Найди букву", "Тренируем зоркость и внимание.", "practice", ["Буквы", "Внимание", "Зоркость", "Игра"]], ["Слоги и короткие слова", "Читаем быстро и без ошибок.", "practice", ["Слоги", "Слова", "Техника", "Скорость"]], ["Читаем по очереди", "Совместное чтение со взрослым.", "practice", ["Совместное чтение", "Темп", "Интерес", "Родитель"]], ["Мой дневник чтения", "Записываем результаты и рекорды.", "practice", ["Дневник", "Результаты", "Мотивация", "Прогресс"]]]}, {"t": "Модуль 2. Видим больше", "d": "Расширяем поле зрения и читаем словами.", "l": [["Клин: читаем одним взглядом", "Строка всё шире — глаз видит больше.", "practice", ["Клин", "Поле зрения", "Взгляд", "Слова"]], ["Флеш-слова", "Узнаём слово за мгновение.", "practice", ["Флеш-слова", "Узнавание", "Скорость", "Память"]], ["Пирамида слов", "Читаем фразами, а не по одному слову.", "practice", ["Пирамида", "Фразы", "Поле зрения", "Чтение"]], ["Указка-помощник", "Не возвращаемся к прочитанному.", "practice", ["Указка", "Регрессии", "Темп", "Ритм"]], ["Таблица Шульте 5×5", "Новый уровень сложности.", "practice", ["Шульте", "5×5", "Внимание", "Рекорд"]], ["Замер №2", "Смотрим, что изменилось.", "practice", ["Замер", "Прогресс", "Сравнение", "График"]]]}, {"t": "Модуль 3. Понимаю, что читаю", "d": "Учимся думать над текстом.", "l": [["Угадай окончание", "Предугадываем слово по смыслу.", "practice", ["Антиципация", "Окончания", "Смысл", "Игра"]], ["Пропущенные слова", "Восстанавливаем предложение.", "practice", ["Пропуски", "Смысл", "Предложения", "Логика"]], ["Вопросы до, во время и после", "Читаем с интересом и вниманием.", "practice", ["Вопросы", "Понимание", "Интерес", "Обсуждение"]], ["Главная мысль", "Кто, что сделал, чем закончилось.", "practice", ["Главная мысль", "Пересказ", "Сюжет", "Герои"]], ["Рисуем рассказ", "Представляем и рисуем прочитанное.", "practice", ["Воображение", "Рисунок", "Понимание", "Память"]], ["Пересказ в трёх предложениях", "Коротко о главном.", "practice", ["Пересказ", "Краткость", "Главное", "Речь"]]]}, {"t": "Модуль 4. Люблю читать", "d": "Книги по интересам и итоговый замер.", "l": [["Книга по интересам", "Как выбрать книгу, которую захочется дочитать.", "practice", ["Книги", "Интересы", "Выбор", "Мотивация"]], ["Читаем энциклопедии", "Короткие познавательные тексты.", "practice", ["Энциклопедия", "Факты", "Познание", "Чтение"]], ["Стихи и скороговорки", "Ритм, дикция и выразительность.", "practice", ["Стихи", "Скороговорки", "Дикция", "Ритм"]], ["Марафон рекордов", "Шульте, клин и флеш-слова на время.", "practice", ["Рекорды", "Тренажёры", "Игра", "Скорость"]], ["Книжный клуб дома", "Обсуждаем книгу всей семьёй.", "practice", ["Обсуждение", "Семья", "Книга", "Интерес"]], ["Финальный замер", "Сравниваем с первым занятием и празднуем.", "project", ["Финальный замер", "Прогресс", "Итоги", "Награда"]]]}]'::jsonb) WITH ORDINALITY AS m(mod, mi)
CROSS JOIN LATERAL jsonb_array_elements(m.mod->'l') WITH ORDINALITY AS l(les, li);